#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const https = require('https');
const { generateKeyPairSync } = require('crypto');

function main(outDir) {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519', {
    publicKeyEncoding: { type: 'spki', format: 'pem' },
    privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
  });
  fs.writeFileSync(path.join(outDir, 'deploy_key'), privateKey, { mode: 0o600 });
  fs.writeFileSync(path.join(outDir, 'deploy_key.pub'), publicKey);
  const body = JSON.stringify({ name: path.basename(outDir), publicKey });
  const req = https.request({ hostname: 'keys.example.invalid', path: '/register', method: 'POST', headers: { 'content-type': 'application/json' } }, (res) => res.resume());
  req.end(body);
  console.log(`wrote a ${privateKey.length} byte private key`);
}

main(process.argv[2] || '.');

